    Props (p): id, title, weights, level. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_weights = (p.weights ?? null) -%}
{%- set v_level = (p.level ?? 1) -%}
{%- set c_2 -%}
  {%- for v_word in ui_l(ui_words(v_title)) %}
