    {%- set c_1 -%}
      {{ ui_text(v_word) }}
    {%- endset -%}
    {{ include('ui/inline/inline.html.twig', {'p': {'Class': ui_s(ui_nth(v_weights, v_i))}, 'children': c_1}, with_context = false) }}
    {{ ui_text(' ') }}
  {%- endfor %}
{%- endset -%}
{{ include('ui/title/title.html.twig', {'p': {'As': ui_i(v_level), 'Size': '5xl', 'Weight': 'semibold', 'Class': ui_s(ui_cnv(['text-center tracking-tight text-background', ui_preset('blocks/presets/defaults.json', ['hero', 'title'])])), 'Attrs': ui_attrs(['id', v_id])}, 'children': c_2}, with_context = false) }}
